INSERT INTO performer (id, name, blurb) VALUES ('marrow-vine', 'Marrow & Vine', 'A two-piece that plays forty-seat rooms on purpose and sells every one of them out.');
INSERT INTO performer (id, name, blurb) VALUES ('glasswing', 'Glasswing Arcade', 'Synth quartet from the Great Lakes with a light rig bigger than their van.');
INSERT INTO performer (id, name, blurb) VALUES ('odile-brandt', 'Odile Brandt Trio', 'Piano, upright bass and brushes. Standards, played slowly.');
INSERT INTO performer (id, name, blurb) VALUES ('herons', 'Harbor City Herons', 'Second in the Coastal Division and loud about it.');
INSERT INTO performer (id, name, blurb) VALUES ('derby', 'Iron Lake Roller Derby', 'Flat-track league now in its eleventh season.');
INSERT INTO performer (id, name, blurb) VALUES ('marigold-co', 'Marigold Repertory Company', 'A resident company of fourteen staging four productions a year.');
INSERT INTO performer (id, name, blurb) VALUES ('dana-okafor', 'Dana Okafor', 'Stand-up about group chats, landlords and her mother''s voicemails.');
INSERT INTO performer (id, name, blurb) VALUES ('after-hours', 'After Hours Improv', 'Six improvisers, one audience suggestion, no script.');
INSERT INTO event (id, venue_id, performer_id, name, description, type, starts_at) VALUES ('hot', 'coat-check', 'marrow-vine', 'Marrow & Vine: The Last Forty', 'One night, forty seats, no opener. The smallest show of the tour and the hardest ticket to get.', 'concert', '2027-02-12T20:00:00Z');
